mapper.select:
SELECT M.*, MG.grade_name AS memberGrade, COALESCE(O.total_payment, 0) AS totalPayment FROM MEMBER M LEFT JOIN MEMBERSHIP_GRADE MG ON M.member_id = MG.member_id LEFT JOIN ( SELECT member_id, SUM(final_amount) AS total_payment FROM ORDERS GROUP BY member_id ) O ON M.member_id = O.member_id
AND ( M.member_name LIKE CONCAT('%', #{keyword}, '%') OR M.login_id LIKE CONCAT('%', #{keyword}, '%') OR M.email LIKE CONCAT('%', #{keyword}, '%') )
AND MG.grade_name = #{searchGrade}
AND M.status = #{searchStatus}
AND M.created_at >= CURDATE() AND M.created_at < CURDATE () + INTERVAL 1 DAY
AND M.created_at >= CURDATE() - INTERVAL 6 DAY AND M.created_at < CURDATE () + INTERVAL 1 DAY
AND M.created_at >= CURDATE() - INTERVAL 29 DAY AND M.created_at < CURDATE () + INTERVAL 1 DAY
ORDER BY M.created_at DESC, M.member_id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE MEMBERSHIP_GRADE

SET
grade_code = CASE #{memberGrade}
WHEN 'BRONZE' THEN '1'
WHEN 'SILVER' THEN '2'
WHEN 'GOLD' THEN '3'
WHEN 'VIP' THEN '4'
END,
grade_name = #{memberGrade}

WHERE member_id = #{memberId}
